import csv

temp_id = 'aa94e675-0b70-525d-8004-da58b0480399'
sp_id = '7bf711cc-b11d-57c7-853c-a96bf1f3b2bc'

data = {temp_id: {}, sp_id: {}}
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r["timeseries_id"] in data:
            ts = r["timestamp"]
            try:
                v = float(r["value"])
            except:
                continue
            data[r["timeseries_id"]][ts] = v

def mean_dev(date):
    devs = []
    for ts, tv in data[temp_id].items():
        if ts.startswith(date) and 8 <= int(ts[11:13]) <= 18:
            if ts in data[sp_id]:
                devs.append(tv - data[sp_id][ts])
    return sum(devs)/len(devs), len(devs)

for d in ["2018-04-03", "2018-10-17"]:
    m, n = mean_dev(d)
    print(d, m, n)
